function process(o, u) {
  const q = o.q;
  const x = q.map(t => t.v);
  const r = x.reduce((a, b) => a + b, 0);
  if (r > 100) {
    u.notify(r);
  }
}

class ReportService {
  fetch(rq) {
    const ds = this.loader.load(rq);
    return this.format(ds);
  }

  format(d) {
    return d.map(x => x.v);
  }
}

/* Version A */
function calc(o) {
  const a = o.items.map(i => i.p);
  return a.reduce((s, v) => s + v, 0);
}

/* Version B */
function calculateInvoiceTotal(order) {
  const prices = order.items.map(item => item.price);
  return prices.reduce((sum, value) => sum + value, 0);
}
